/* 小型表格/证据组件；不构建页面布局。 */
window.EamWorkUi=(()=>{const $=id=>document.getElementById(id);let config={},people=[];const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};const name=id=>people.find(p=>p.id===id)?.name||id||'未指派';const label=x=>config.labels?.[x]||x||'未记录';const badge=x=>{const e=node('span',label(x),'problem-badge');e.dataset.state=x;return e;};const button=(text,fn,cls)=>{const e=node('button',text,cls);e.type='button';e.onclick=fn;return e;};const link=(text,fn)=>button(text,fn,'work-link');const pages={defects:'defect-list',failures:'failure-events',hazards:'hazards',discoveries:'abnormal-events'};const openProblem=(kind,id)=>Eam.go(pages[kind],{id});const row=(body,values,headers)=>{const tr=node('tr');values.forEach((value,i)=>{const td=node('td');td.dataset.label=headers[i];if(value instanceof Node)td.append(value);else td.textContent=value??'—';tr.append(td);});body.append(tr);return tr;};const facts=(target,values)=>{target.replaceChildren();for(const [title,value]of values){const div=node('div');div.append(node('dt',title),node('dd',value??'未记录'));target.append(div);}};
function audit(target,events){target.replaceChildren();if(!events?.length){target.append(node('p','初始化样本；暂无本会话操作','muted'));return;}for(const e of events){const item=node('details',undefined,'work-history');item.append(node('summary',EamProduct.time(e.at)+' · '+name(e.actorId)+' · '+(config.actionLabels?.[e.action]||(e.action==='accept_linked'?'工单技术验收送验证':e.action))));item.append(node('p',e.reason));const after=e.after;const before=e.before;if(before?.evidence)item.append(node('p','操作前证据：'+before.evidence));if(after?.evidence)item.append(node('p','操作后证据：'+after.evidence));if(after?.review)item.append(node('p','复查证据：'+after.review.evidence));if(after?.restriction?.evidence)item.append(node('p','放行证据：'+after.restriction.evidence));if(after?.execution){item.append(node('p','执行V'+after.execution.revision+'：'+(after.execution.measures||'草稿')));for(const o of after.execution.outcomes||[])item.append(node('p',o.id+' · '+label(o.result)+' · '+o.evidence));}target.append(item);}}
const field=(parent,title,type,options=[])=>{const wrap=node('label',title,'field');const el=node(type==='select'?'select':type==='textarea'?'textarea':'input');if(el.tagName==='INPUT')el.type=type;if(type==='select')for(const opt of options)el.add(new Option(opt.label,opt.value));wrap.append(el);parent.append(wrap);return el;};const init=async()=>{const api=EamProblemApi;config=await api.request('GET','/work-config');people=(await api.request('GET','/people')).rows;return config;};return {$,node,name,label,badge,button,link,openProblem,row,facts,audit,field,init,get config(){return config;}};})();
